1	package config
2	
3	import (
4		"fmt"
5	
6		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
7	)
8	
9	// DecisionPlugin represents a plugin configuration for a decision.
10	// Type is the plugin identifier; the authoritative supported set is registered in
11	// routing_surface_catalog (and DSL/compiler surfaces), not duplicated here.
12	type DecisionPlugin struct {
13		Type string `yaml:"type" json:"type"`
14	
15		// Configuration stores the plugin payload as normalized structured bytes.
16		Configuration *StructuredPayload `yaml:"configuration,omitempty" json:"configuration,omitempty"`
17	}
18	
19	// SemanticCachePluginConfig represents configuration for semantic-cache plugin.
20	type SemanticCachePluginConfig struct {
21		Enabled             bool     `json:"enabled" yaml:"enabled"`
22		SimilarityThreshold *float32 `json:"similarity_threshold,omitempty" yaml:"similarity_threshold,omitempty"`
23		TTLSeconds          *int     `json:"ttl_seconds,omitempty" yaml:"ttl_seconds,omitempty"`
24	}
25	
26	// MemoryPluginConfig is per-decision memory config (overrides global MemoryConfig).
27	type MemoryPluginConfig struct {
28		Enabled             bool                    `json:"enabled" yaml:"enabled"`
29		RetrievalLimit      *int                    `json:"retrieval_limit,omitempty" yaml:"retrieval_limit,omitempty"`
30		SimilarityThreshold *float32                `json:"similarity_threshold,omitempty" yaml:"similarity_threshold,omitempty"`
31		AutoStore           *bool                   `json:"auto_store,omitempty" yaml:"auto_store,omitempty"`
32		HybridSearch        bool                    `json:"hybrid_search,omitempty" yaml:"hybrid_search,omitempty"`
33		HybridMode          string                  `json:"hybrid_mode,omitempty" yaml:"hybrid_mode,omitempty"`
34		Reflection          *MemoryReflectionConfig `json:"reflection,omitempty" yaml:"reflection,omitempty"`
35	}
36	
37	// FastResponsePluginConfig represents configuration for fast_response plugin.
38	type FastResponsePluginConfig struct {
39		Message string `json:"message" yaml:"message"`
40	}
41	
42	// RequestParamsPluginConfig represents configuration for request_params plugin.
43	// This plugin validates and strips request body parameters per decision.
44	type RequestParamsPluginConfig struct {
45		// BlockedParams is a list of parameters that should be blocked/stripped.
46		BlockedParams []string `json:"blocked_params,omitempty" yaml:"blocked_params,omitempty"`
47		// MaxTokensLimit sets the maximum allowed value for max_tokens.
48		MaxTokensLimit *int `json:"max_tokens_limit,omitempty" yaml:"max_tokens_limit,omitempty"`
49		// MaxN is the maximum allowed value for n (number of completions).
50		MaxN *int `json:"max_n,omitempty" yaml:"max_n,omitempty"`
51		// StripUnknown if true, removes fields not in the OpenAI spec.
52		StripUnknown bool `json:"strip_unknown,omitempty" yaml:"strip_unknown,omitempty"`
53	}
54	
55	// SystemPromptPluginConfig represents configuration for system_prompt plugin.
56	type SystemPromptPluginConfig struct {
57		Enabled      *bool  `json:"enabled,omitempty" yaml:"enabled,omitempty"`
58		SystemPrompt string `json:"system_prompt,omitempty" yaml:"system_prompt,omitempty"`
59		Mode         string `json:"mode,omitempty" yaml:"mode,omitempty"`
60	}
61	
62	// HeaderMutationPluginConfig represents configuration for header_mutation plugin.
63	type HeaderMutationPluginConfig struct {
64		Add    []HeaderPair `json:"add,omitempty" yaml:"add,omitempty"`
65		Update []HeaderPair `json:"update,omitempty" yaml:"update,omitempty"`
66		Delete []string     `json:"delete,omitempty" yaml:"delete,omitempty"`
67	}
68	
69	// HeaderPair represents a header name-value pair.
70	type HeaderPair struct {
71		Name  string `json:"name" yaml:"name"`
72		Value string `json:"value" yaml:"value"`
73	}
74	
75	// ResponseJailbreakPluginConfig represents configuration for response-level jailbreak detection.
76	type ResponseJailbreakPluginConfig struct {
77		Enabled   bool    `json:"enabled" yaml:"enabled"`
78		Threshold float32 `json:"threshold,omitempty" yaml:"threshold,omitempty"`
79		Action    string  `json:"action,omitempty" yaml:"action,omitempty"`
80	}
81	
82	// HallucinationPluginConfig represents configuration for hallucination detection plugin.
83	type HallucinationPluginConfig struct {
84		Enabled                     bool   `json:"enabled" yaml:"enabled"`
85		UseNLI                      bool   `json:"use_nli,omitempty" yaml:"use_nli,omitempty"`
86		HallucinationAction         string `json:"hallucination_action,omitempty" yaml:"hallucination_action,omitempty"`
87		UnverifiedFactualAction     string `json:"unverified_factual_action,omitempty" yaml:"unverified_factual_action,omitempty"`
88		IncludeHallucinationDetails bool   `json:"include_hallucination_details,omitempty" yaml:"include_hallucination_details,omitempty"`
89	}
90	
91	// RouterReplayPluginConfig represents configuration for router_replay plugin.
92	type RouterReplayPluginConfig struct {
93		Enabled             bool `json:"enabled" yaml:"enabled"`
94		MaxRecords          int  `json:"max_records,omitempty" yaml:"max_records,omitempty"`
95		CaptureRequestBody  bool `json:"capture_request_body,omitempty" yaml:"capture_request_body,omitempty"`
96		CaptureResponseBody bool `json:"capture_response_body,omitempty" yaml:"capture_response_body,omitempty"`
97		MaxBodyBytes        int  `json:"max_body_bytes,omitempty" yaml:"max_body_bytes,omitempty"`
98		// MaxToolTraceBytes caps each structured tool-trace field (Prompt,
99		// ToolDefinitions, ToolTraceStep.Arguments, ToolTraceStep.Output).
100		// 0 means no limit. Configurable independently of MaxBodyBytes so that
101		// structured fields remain complete even when the raw body is truncated.
102		MaxToolTraceBytes int `json:"max_tool_trace_bytes,omitempty" yaml:"max_tool_trace_bytes,omitempty"`
103		// MaxToolTraceSteps caps the number of ToolTraceStep entries retained per
104		// record. Long agent sessions produce one step per tool-call turn, so an
105		// unbounded chain (e.g. a runaway hermes-style loop) can otherwise grow
106		// without limit and OOM the router process. When the cap is exceeded the
107		// oldest steps are dropped and ToolTrace.StepsTruncated is set so callers
108		// can see that a cap was applied. 0 means no limit.
109		MaxToolTraceSteps int `json:"max_tool_trace_steps,omitempty" yaml:"max_tool_trace_steps,omitempty"`
110	}
111	
112	// GetPlugin returns the plugin entry for a specific plugin type.
113	func (d *Decision) GetPlugin(pluginType string) *DecisionPlugin {
114		normalizedTarget := NormalizeDecisionPluginType(pluginType)
115		for i := range d.Plugins {
116			if NormalizeDecisionPluginType(d.Plugins[i].Type) == normalizedTarget {
117				return &d.Plugins[i]
118			}
119		}
120		return nil
121	}
122	
123	// HasPlugin reports whether the decision includes a plugin of the given type.
124	func (d *Decision) HasPlugin(pluginType string) bool {
125		return d.GetPlugin(pluginType) != nil
126	}
127	
128	// UnmarshalPluginConfig converts a plugin payload into the given target struct.
129	func UnmarshalPluginConfig(config *StructuredPayload, target interface{}) error {
130		if config == nil {
131			return fmt.Errorf("plugin configuration is nil")
132		}
133		return config.DecodeInto(target)
134	}
135	
136	// GetSemanticCacheConfig returns the semantic-cache plugin configuration.
137	func (d *Decision) GetSemanticCacheConfig() *SemanticCachePluginConfig {
138		result := &SemanticCachePluginConfig{}
139		return decodeDecisionPlugin(d, "semantic-cache", result)
140	}
141	
142	// GetSystemPromptConfig returns the system_prompt plugin configuration.
143	func (d *Decision) GetSystemPromptConfig() *SystemPromptPluginConfig {
144		result := &SystemPromptPluginConfig{}
145		return decodeDecisionPlugin(d, "system_prompt", result)
146	}
147	
148	// GetHeaderMutationConfig returns the header_mutation plugin configuration.
149	func (d *Decision) GetHeaderMutationConfig() *HeaderMutationPluginConfig {
150		result := &HeaderMutationPluginConfig{}
151		return decodeDecisionPlugin(d, "header_mutation", result)
152	}
153	
154	// GetHallucinationConfig returns the hallucination plugin configuration.
155	func (d *Decision) GetHallucinationConfig() *HallucinationPluginConfig {
156		result := &HallucinationPluginConfig{}
157		return decodeDecisionPlugin(d, "hallucination", result)
158	}
159	
160	// GetResponseJailbreakConfig returns the response_jailbreak plugin configuration.
161	func (d *Decision) GetResponseJailbreakConfig() *ResponseJailbreakPluginConfig {
162		result := &ResponseJailbreakPluginConfig{}
163		return decodeDecisionPlugin(d, "response_jailbreak", result)
164	}
165	
166	// GetRouterReplayConfig returns the router_replay plugin configuration.
167	func (d *Decision) GetRouterReplayConfig() *RouterReplayPluginConfig {
168		result := &RouterReplayPluginConfig{}
169		return decodeDecisionPlugin(d, "router_replay", result)
170	}
171	
172	// GetMemoryConfig returns the memory plugin config, or nil to use global config.
173	func (d *Decision) GetMemoryConfig() *MemoryPluginConfig {
174		result := &MemoryPluginConfig{}
175		return decodeDecisionPlugin(d, "memory", result)
176	}
177	
178	// GetFastResponseConfig returns the fast_response plugin configuration.
179	func (d *Decision) GetFastResponseConfig() *FastResponsePluginConfig {
180		result := &FastResponsePluginConfig{}
181		return decodeDecisionPlugin(d, "fast_response", result)
182	}
183	
184	// GetRequestParamsConfig returns the request_params plugin configuration.
185	func (d *Decision) GetRequestParamsConfig() *RequestParamsPluginConfig {
186		result := &RequestParamsPluginConfig{}
187		return decodeDecisionPlugin(d, "request_params", result)
188	}
189	
190	// IsRAGEnabledForDecision returns whether RAG is enabled for a specific decision.
191	// Checks the per-decision RAG plugin config (enabled: true).
192	func (c *RouterConfig) IsRAGEnabledForDecision(decisionName string) bool {
193		decision := c.GetDecisionByName(decisionName)
194		if decision == nil {
195			return false
196		}
197		ragConfig := decision.GetRAGConfig()
198		return ragConfig != nil && ragConfig.Enabled
199	}
200	
201	// IsMemoryEnabledForDecision returns whether memory is enabled for a specific decision.
202	// A decision has memory enabled if:
203	//   - It has a per-decision memory plugin with enabled: true, OR
204	//   - Global memory is enabled and the decision does NOT have a per-decision
205	//     memory plugin that explicitly disables it.
206	func (c *RouterConfig) IsMemoryEnabledForDecision(decisionName string) bool {
207		decision := c.GetDecisionByName(decisionName)
208		if decision == nil {
209			return c.Memory.Enabled
210		}
211		memConfig := decision.GetMemoryConfig()
212		if memConfig != nil {
213			return memConfig.Enabled
214		}
215		return c.Memory.Enabled
216	}
217	
218	// HasPersonalizationPlugins returns true if the decision has RAG or memory
219	// enabled, meaning cached responses would miss personalized context.
220	func (c *RouterConfig) HasPersonalizationPlugins(decisionName string) bool {
221		return c.IsRAGEnabledForDecision(decisionName) || c.IsMemoryEnabledForDecision(decisionName)
222	}
223	
224	func decodeDecisionPlugin[T any](d *Decision, pluginType string, result *T) *T {
225		plugin := d.GetPlugin(pluginType)
226		if plugin == nil || plugin.Configuration == nil {
227			return nil
228		}
229	
230		if err := UnmarshalPluginConfig(plugin.Configuration, result); err != nil {
231			logging.Errorf("Failed to unmarshal %s config: %v", pluginType, err)
232			return nil
233		}
234		return result
235	}
