package config

import (
	"fmt"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
)

// DecisionPlugin represents a plugin configuration for a decision.
// Type is the plugin identifier; the authoritative supported set is registered in
// routing_surface_catalog (and DSL/compiler surfaces), not duplicated here.
type DecisionPlugin struct {
	Type string `yaml:"type" json:"type"`

	// Configuration stores the plugin payload as normalized structured bytes.
	Configuration *StructuredPayload `yaml:"configuration,omitempty" json:"configuration,omitempty"`
}

// SemanticCachePluginConfig represents configuration for semantic-cache plugin.
type SemanticCachePluginConfig struct {
	Enabled             bool     `json:"enabled" yaml:"enabled"`
	SimilarityThreshold *float32 `json:"similarity_threshold,omitempty" yaml:"similarity_threshold,omitempty"`
	TTLSeconds          *int     `json:"ttl_seconds,omitempty" yaml:"ttl_seconds,omitempty"`
}

// MemoryPluginConfig is per-decision memory config (overrides global MemoryConfig).
type MemoryPluginConfig struct {
	Enabled             bool                    `json:"enabled" yaml:"enabled"`
	RetrievalLimit      *int                    `json:"retrieval_limit,omitempty" yaml:"retrieval_limit,omitempty"`
	SimilarityThreshold *float32                `json:"similarity_threshold,omitempty" yaml:"similarity_threshold,omitempty"`
	AutoStore           *bool                   `json:"auto_store,omitempty" yaml:"auto_store,omitempty"`
	HybridSearch        bool                    `json:"hybrid_search,omitempty" yaml:"hybrid_search,omitempty"`
	HybridMode          string                  `json:"hybrid_mode,omitempty" yaml:"hybrid_mode,omitempty"`
	Reflection          *MemoryReflectionConfig `json:"reflection,omitempty" yaml:"reflection,omitempty"`
}

// FastResponsePluginConfig represents configuration for fast_response plugin.
type FastResponsePluginConfig struct {
	Message string `json:"message" yaml:"message"`
}

// RequestParamsPluginConfig represents configuration for request_params plugin.
// This plugin validates and strips request body parameters per decision.
type RequestParamsPluginConfig struct {
	// BlockedParams is a list of parameters that should be blocked/stripped.
	BlockedParams []string `json:"blocked_params,omitempty" yaml:"blocked_params,omitempty"`
	// MaxTokensLimit sets the maximum allowed value for max_tokens.
	MaxTokensLimit *int `json:"max_tokens_limit,omitempty" yaml:"max_tokens_limit,omitempty"`
	// MaxN is the maximum allowed value for n (number of completions).
	MaxN *int `json:"max_n,omitempty" yaml:"max_n,omitempty"`
	// StripUnknown if true, removes fields not in the OpenAI spec.
	StripUnknown bool `json:"strip_unknown,omitempty" yaml:"strip_unknown,omitempty"`
}

// SystemPromptPluginConfig represents configuration for system_prompt plugin.
type SystemPromptPluginConfig struct {
	Enabled      *bool  `json:"enabled,omitempty" yaml:"enabled,omitempty"`
	SystemPrompt string `json:"system_prompt,omitempty" yaml:"system_prompt,omitempty"`
	Mode         string `json:"mode,omitempty" yaml:"mode,omitempty"`
}

// HeaderMutationPluginConfig represents configuration for header_mutation plugin.
type HeaderMutationPluginConfig struct {
	Add    []HeaderPair `json:"add,omitempty" yaml:"add,omitempty"`
	Update []HeaderPair `json:"update,omitempty" yaml:"update,omitempty"`
	Delete []string     `json:"delete,omitempty" yaml:"delete,omitempty"`
}

// HeaderPair represents a header name-value pair.
type HeaderPair struct {
	Name  string `json:"name" yaml:"name"`
	Value string `json:"value" yaml:"value"`
}

// ResponseJailbreakPluginConfig represents configuration for response-level jailbreak detection.
type ResponseJailbreakPluginConfig struct {
	Enabled   bool    `json:"enabled" yaml:"enabled"`
	Threshold float32 `json:"threshold,omitempty" yaml:"threshold,omitempty"`
	Action    string  `json:"action,omitempty" yaml:"action,omitempty"`
}

// HallucinationPluginConfig represents configuration for hallucination detection plugin.
type HallucinationPluginConfig struct {
	Enabled                     bool   `json:"enabled" yaml:"enabled"`
	UseNLI                      bool   `json:"use_nli,omitempty" yaml:"use_nli,omitempty"`
	HallucinationAction         string `json:"hallucination_action,omitempty" yaml:"hallucination_action,omitempty"`
	UnverifiedFactualAction     string `json:"unverified_factual_action,omitempty" yaml:"unverified_factual_action,omitempty"`
	IncludeHallucinationDetails bool   `json:"include_hallucination_details,omitempty" yaml:"include_hallucination_details,omitempty"`
}

// RouterReplayPluginConfig represents configuration for router_replay plugin.
type RouterReplayPluginConfig struct {
	Enabled             bool `json:"enabled" yaml:"enabled"`
	MaxRecords          int  `json:"max_records,omitempty" yaml:"max_records,omitempty"`
	CaptureRequestBody  bool `json:"capture_request_body,omitempty" yaml:"capture_request_body,omitempty"`
	CaptureResponseBody bool `json:"capture_response_body,omitempty" yaml:"capture_response_body,omitempty"`
	MaxBodyBytes        int  `json:"max_body_bytes,omitempty" yaml:"max_body_bytes,omitempty"`
	// MaxToolTraceBytes caps each structured tool-trace field (Prompt,
	// ToolDefinitions, ToolTraceStep.Arguments, ToolTraceStep.Output).
	// 0 means no limit. Configurable independently of MaxBodyBytes so that
	// structured fields remain complete even when the raw body is truncated.
	MaxToolTraceBytes int `json:"max_tool_trace_bytes,omitempty" yaml:"max_tool_trace_bytes,omitempty"`
	// MaxToolTraceSteps caps the number of ToolTraceStep entries retained per
	// record. Long agent sessions produce one step per tool-call turn, so an
	// unbounded chain (e.g. a runaway hermes-style loop) can otherwise grow
	// without limit and OOM the router process. When the cap is exceeded the
	// oldest steps are dropped and ToolTrace.StepsTruncated is set so callers
	// can see that a cap was applied. 0 means no limit.
	MaxToolTraceSteps int `json:"max_tool_trace_steps,omitempty" yaml:"max_tool_trace_steps,omitempty"`
}

// GetPlugin returns the plugin entry for a specific plugin type.
func (d *Decision) GetPlugin(pluginType string) *DecisionPlugin {
	normalizedTarget := NormalizeDecisionPluginType(pluginType)
	for i := range d.Plugins {
		if NormalizeDecisionPluginType(d.Plugins[i].Type) == normalizedTarget {
			return &d.Plugins[i]
		}
	}
	return nil
}

// HasPlugin reports whether the decision includes a plugin of the given type.
func (d *Decision) HasPlugin(pluginType string) bool {
	return d.GetPlugin(pluginType) != nil
}

// UnmarshalPluginConfig converts a plugin payload into the given target struct.
func UnmarshalPluginConfig(config *StructuredPayload, target interface{}) error {
	if config == nil {
		return fmt.Errorf("plugin configuration is nil")
	}
	return config.DecodeInto(target)
}

// GetSemanticCacheConfig returns the semantic-cache plugin configuration.
func (d *Decision) GetSemanticCacheConfig() *SemanticCachePluginConfig {
	result := &SemanticCachePluginConfig{}
	return decodeDecisionPlugin(d, "semantic-cache", result)
}

// GetSystemPromptConfig returns the system_prompt plugin configuration.
func (d *Decision) GetSystemPromptConfig() *SystemPromptPluginConfig {
	result := &SystemPromptPluginConfig{}
	return decodeDecisionPlugin(d, "system_prompt", result)
}

// GetHeaderMutationConfig returns the header_mutation plugin configuration.
func (d *Decision) GetHeaderMutationConfig() *HeaderMutationPluginConfig {
	result := &HeaderMutationPluginConfig{}
	return decodeDecisionPlugin(d, "header_mutation", result)
}

// GetHallucinationConfig returns the hallucination plugin configuration.
func (d *Decision) GetHallucinationConfig() *HallucinationPluginConfig {
	result := &HallucinationPluginConfig{}
	return decodeDecisionPlugin(d, "hallucination", result)
}

// GetResponseJailbreakConfig returns the response_jailbreak plugin configuration.
func (d *Decision) GetResponseJailbreakConfig() *ResponseJailbreakPluginConfig {
	result := &ResponseJailbreakPluginConfig{}
	return decodeDecisionPlugin(d, "response_jailbreak", result)
}

// GetRouterReplayConfig returns the router_replay plugin configuration.
func (d *Decision) GetRouterReplayConfig() *RouterReplayPluginConfig {
	result := &RouterReplayPluginConfig{}
	return decodeDecisionPlugin(d, "router_replay", result)
}

// GetMemoryConfig returns the memory plugin config, or nil to use global config.
func (d *Decision) GetMemoryConfig() *MemoryPluginConfig {
	result := &MemoryPluginConfig{}
	return decodeDecisionPlugin(d, "memory", result)
}

// GetFastResponseConfig returns the fast_response plugin configuration.
func (d *Decision) GetFastResponseConfig() *FastResponsePluginConfig {
	result := &FastResponsePluginConfig{}
	return decodeDecisionPlugin(d, "fast_response", result)
}

// GetRequestParamsConfig returns the request_params plugin configuration.
func (d *Decision) GetRequestParamsConfig() *RequestParamsPluginConfig {
	result := &RequestParamsPluginConfig{}
	return decodeDecisionPlugin(d, "request_params", result)
}

// IsRAGEnabledForDecision returns whether RAG is enabled for a specific decision.
// Checks the per-decision RAG plugin config (enabled: true).
func (c *RouterConfig) IsRAGEnabledForDecision(decisionName string) bool {
	decision := c.GetDecisionByName(decisionName)
	if decision == nil {
		return false
	}
	ragConfig := decision.GetRAGConfig()
	return ragConfig != nil && ragConfig.Enabled
}

// IsMemoryEnabledForDecision returns whether memory is enabled for a specific decision.
// A decision has memory enabled if:
//   - It has a per-decision memory plugin with enabled: true, OR
//   - Global memory is enabled and the decision does NOT have a per-decision
//     memory plugin that explicitly disables it.
func (c *RouterConfig) IsMemoryEnabledForDecision(decisionName string) bool {
	decision := c.GetDecisionByName(decisionName)
	if decision == nil {
		return c.Memory.Enabled
	}
	memConfig := decision.GetMemoryConfig()
	if memConfig != nil {
		return memConfig.Enabled
	}
	return c.Memory.Enabled
}

// HasPersonalizationPlugins returns true if the decision has RAG or memory
// enabled, meaning cached responses would miss personalized context.
func (c *RouterConfig) HasPersonalizationPlugins(decisionName string) bool {
	return c.IsRAGEnabledForDecision(decisionName) || c.IsMemoryEnabledForDecision(decisionName)
}

func decodeDecisionPlugin[T any](d *Decision, pluginType string, result *T) *T {
	plugin := d.GetPlugin(pluginType)
	if plugin == nil || plugin.Configuration == nil {
		return nil
	}

	if err := UnmarshalPluginConfig(plugin.Configuration, result); err != nil {
		logging.Errorf("Failed to unmarshal %s config: %v", pluginType, err)
		return nil
	}
	return result
}

package config

import "sort"

const (
	DecisionAlgorithmAutoMix      = "automix"
	DecisionAlgorithmConfidence   = "confidence"
	DecisionAlgorithmFusion       = "fusion"
	DecisionAlgorithmHybrid       = "hybrid"
	DecisionAlgorithmKMeans       = "kmeans"
	DecisionAlgorithmKNN          = "knn"
	DecisionAlgorithmLatencyAware = "latency_aware"
	DecisionAlgorithmMLP          = "mlp"
	DecisionAlgorithmMultiFactor  = "multi_factor"
	DecisionAlgorithmRatings      = "ratings"
	DecisionAlgorithmReMoM        = "remom"
	DecisionAlgorithmRouterDC     = "router_dc"
	DecisionAlgorithmStatic       = "static"
	DecisionAlgorithmSVM          = "svm"
	DecisionAlgorithmWorkflows    = "workflows"
	DecisionAlgorithmPrompt       = "prompt"

	DecisionPluginSemanticCache     = "semantic-cache"
	DecisionPluginSystemPrompt      = "system_prompt"
	DecisionPluginHeaderMutation    = "header_mutation"
	DecisionPluginHallucination     = "hallucination"
	DecisionPluginResponseJailbreak = "response_jailbreak"
	DecisionPluginRouterReplay      = "router_replay"
	DecisionPluginMemory            = "memory"
	DecisionPluginRAG               = "rag"
	DecisionPluginImageGen          = "image_gen"
	DecisionPluginFastResponse      = "fast_response"
	DecisionPluginRequestParams     = "request_params"
	DecisionPluginToolSelection     = "tool_selection"
)

var supportedSignalTypes = []string{
	SignalTypeAuthz,
	SignalTypeComplexity,
	SignalTypeContext,
	SignalTypeConversation,
	SignalTypeDomain,
	SignalTypeEmbedding,
	SignalTypeFactCheck,
	SignalTypeJailbreak,
	SignalTypeKeyword,
	SignalTypeLanguage,
	SignalTypeModality,
	SignalTypePII,
	SignalTypePreference,
	SignalTypeReask,
	SignalTypeStructure,
	SignalTypeKB,
	SignalTypeUserFeedback,
	SignalTypeEvent,
	SignalTypeMetadata,
	SignalTypeClassifier,
}

var supportedDecisionPluginTypes = []string{
	DecisionPluginFastResponse,
	DecisionPluginHallucination,
	DecisionPluginHeaderMutation,
	DecisionPluginImageGen,
	DecisionPluginMemory,
	DecisionPluginRAG,
	DecisionPluginRequestParams,
	DecisionPluginResponseJailbreak,
	DecisionPluginRouterReplay,
	DecisionPluginSemanticCache,
	DecisionPluginSystemPrompt,
	DecisionPluginToolSelection,
	DecisionPluginTools,
}

// AlgorithmCatalogEntry describes a model-selection algorithm and its tier
type AlgorithmCatalogEntry struct {
	Type string // algorithm type name (e.g., "elo")
	Tier string // "supported" or "experimental"
}

var decisionAlgorithmCatalog = []AlgorithmCatalogEntry{
	{Type: DecisionAlgorithmAutoMix, Tier: "experimental"},
	{Type: DecisionAlgorithmConfidence, Tier: "supported"},
	{Type: DecisionAlgorithmFusion, Tier: "experimental"},
	{Type: DecisionAlgorithmHybrid, Tier: "supported"},
	{Type: DecisionAlgorithmKMeans, Tier: "experimental"},
	{Type: DecisionAlgorithmKNN, Tier: "experimental"},
	{Type: DecisionAlgorithmLatencyAware, Tier: "supported"},
	{Type: DecisionAlgorithmMLP, Tier: "experimental"},
	{Type: DecisionAlgorithmMultiFactor, Tier: "supported"},
	{Type: DecisionAlgorithmRatings, Tier: "supported"},
	{Type: DecisionAlgorithmReMoM, Tier: "supported"},
	{Type: DecisionAlgorithmRouterDC, Tier: "supported"},
	{Type: DecisionAlgorithmStatic, Tier: "supported"},
	{Type: DecisionAlgorithmSVM, Tier: "experimental"},
	{Type: DecisionAlgorithmWorkflows, Tier: "experimental"},
	{Type: DecisionAlgorithmPrompt, Tier: "experimental"},
}

// supportedDecisionAlgorithmTypes is derived from the catalog for backwards compatibility
var supportedDecisionAlgorithmTypes = func() []string {
	types := make([]string, len(decisionAlgorithmCatalog))
	for i, entry := range decisionAlgorithmCatalog {
		types[i] = entry.Type
	}
	return types
}()

var pluginTypeAliases = map[string]string{
	"semantic_cache": DecisionPluginSemanticCache,
}

func SupportedSignalTypes() []string {
	return cloneSortedStrings(supportedSignalTypes)
}

func IsSupportedSignalType(signalType string) bool {
	for _, candidate := range supportedSignalTypes {
		if candidate == signalType {
			return true
		}
	}
	return false
}

func SupportedDecisionPluginTypes() []string {
	return cloneSortedStrings(supportedDecisionPluginTypes)
}

func NormalizeDecisionPluginType(pluginType string) string {
	if normalized, ok := pluginTypeAliases[pluginType]; ok {
		return normalized
	}
	return pluginType
}

func IsSupportedDecisionPluginType(pluginType string) bool {
	normalized := NormalizeDecisionPluginType(pluginType)
	for _, candidate := range supportedDecisionPluginTypes {
		if candidate == normalized {
			return true
		}
	}
	return false
}

func SupportedDecisionAlgorithmTypes() []string {
	return cloneSortedStrings(supportedDecisionAlgorithmTypes)
}

func IsSupportedDecisionAlgorithmType(algorithmType string) bool {
	for _, candidate := range supportedDecisionAlgorithmTypes {
		if candidate == algorithmType {
			return true
		}
	}
	return false
}

// DecisionAlgorithmCatalog returns the full structured catalog of algorithm types and tiers
func DecisionAlgorithmCatalog() []AlgorithmCatalogEntry {
	result := make([]AlgorithmCatalogEntry, len(decisionAlgorithmCatalog))
	copy(result, decisionAlgorithmCatalog)
	return result
}

// GetAlgorithmTier returns the tier for a given algorithm type, or empty string if unknown
func GetAlgorithmTier(algorithmType string) string {
	for _, entry := range decisionAlgorithmCatalog {
		if entry.Type == algorithmType {
			return entry.Tier
		}
	}
	return ""
}

func cloneSortedStrings(values []string) []string {
	cloned := append([]string(nil), values...)
	sort.Strings(cloned)
	return cloned
}

package extproc

import (
	"fmt"
	"strings"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/routerreplay"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/routerreplay/store"
)

func createReplayRuntime(cfg *config.RouterConfig) (map[string]*routerreplay.Recorder, *routerreplay.Recorder, bool) {
	backend := resolveReplayStoreBackend(cfg.RouterReplay)
	if usesSharedReplayStorage(backend) {
		recorders, replayRecorder := initializeSharedReplayRecorders(cfg, backend)
		return recorders, replayRecorder, replayRecorder != nil
	}

	replayRecorders := initializeReplayRecorders(cfg)

	var replayRecorder *routerreplay.Recorder
	for _, recorder := range replayRecorders {
		replayRecorder = recorder
		break
	}

	return replayRecorders, replayRecorder, false
}

// initializeReplayRecorders creates replay recorders for decisions with router_replay plugin configured.
func initializeReplayRecorders(cfg *config.RouterConfig) map[string]*routerreplay.Recorder {
	backend := resolveReplayStoreBackend(cfg.RouterReplay)
	if usesSharedReplayStorage(backend) {
		recorders, _ := initializeSharedReplayRecorders(cfg, backend)
		return recorders
	}
	return initializeIsolatedReplayRecorders(cfg, backend)
}

func initializeIsolatedReplayRecorders(
	cfg *config.RouterConfig,
	backend string,
) map[string]*routerreplay.Recorder {
	recorders := make(map[string]*routerreplay.Recorder)

	for _, ref := range cfg.RoutingDecisionRefs() {
		decision := ref.Decision
		pluginCfg := cfg.EffectiveRouterReplayConfig(decision)
		if pluginCfg == nil {
			continue
		}
		key := config.RoutingDecisionKey(ref.Recipe, decision.Name)

		recorder, err := createReplayRecorder(key, backend, pluginCfg, &cfg.RouterReplay)
		if err != nil {
			logging.Errorf("Failed to initialize replay recorder for decision %s: %v", decision.Name, err)
			continue
		}

		recorders[key] = recorder
	}

	return recorders
}

func initializeSharedReplayRecorders(
	cfg *config.RouterConfig,
	backend string,
) (map[string]*routerreplay.Recorder, *routerreplay.Recorder) {
	recorders := make(map[string]*routerreplay.Recorder)
	var (
		sharedStore    store.Storage
		replayRecorder *routerreplay.Recorder
	)

	for _, ref := range cfg.RoutingDecisionRefs() {
		decision := ref.Decision
		pluginCfg := cfg.EffectiveRouterReplayConfig(decision)
		if pluginCfg == nil {
			continue
		}

		if sharedStore == nil {
			storage, err := createSharedReplayStore(backend, &cfg.RouterReplay)
			if err != nil {
				logging.Errorf("Failed to initialize shared replay store for backend %s: %v", backend, err)
				return map[string]*routerreplay.Recorder{}, nil
			}
			sharedStore = storage
		}

		recorder := createSharedReplayRecorder(sharedStore, pluginCfg)
		recorders[config.RoutingDecisionKey(ref.Recipe, decision.Name)] = recorder
		if replayRecorder == nil {
			replayRecorder = recorder
		}
	}

	return recorders, replayRecorder
}

// createReplayRecorder creates a single replay recorder with the appropriate storage backend.
func createReplayRecorder(
	decisionName string,
	backend string,
	pluginCfg *config.RouterReplayPluginConfig,
	globalCfg *config.RouterReplayConfig,
) (*routerreplay.Recorder, error) {
	maxBodyBytes := resolveReplayMaxBodyBytes(pluginCfg.MaxBodyBytes)

	storage, err := createReplayStore(decisionName, backend, pluginCfg, globalCfg)
	if err != nil {
		return nil, err
	}

	recorder := routerreplay.NewRecorder(storage)
	recorder.SetCapturePolicy(pluginCfg.CaptureRequestBody, pluginCfg.CaptureResponseBody, maxBodyBytes)
	recorder.SetMaxToolTraceBytes(pluginCfg.MaxToolTraceBytes)
	recorder.SetMaxToolTraceSteps(pluginCfg.MaxToolTraceSteps)
	return recorder, nil
}

func createSharedReplayRecorder(
	storage store.Storage,
	pluginCfg *config.RouterReplayPluginConfig,
) *routerreplay.Recorder {
	recorder := routerreplay.NewRecorder(storage)
	recorder.SetCapturePolicy(
		pluginCfg.CaptureRequestBody,
		pluginCfg.CaptureResponseBody,
		resolveReplayMaxBodyBytes(pluginCfg.MaxBodyBytes),
	)
	recorder.SetMaxToolTraceBytes(pluginCfg.MaxToolTraceBytes)
	recorder.SetMaxToolTraceSteps(pluginCfg.MaxToolTraceSteps)
	return recorder
}

func usesSharedReplayStorage(backend string) bool {
	switch backend {
	case "postgres", "redis", "milvus", "qdrant":
		return true
	default:
		return false
	}
}

func resolveReplayStoreBackend(cfg config.RouterReplayConfig) string {
	if backend := strings.ToLower(strings.TrimSpace(cfg.StoreBackend)); backend != "" {
		return backend
	}
	if cfg.Postgres != nil {
		return "postgres"
	}
	if cfg.Redis != nil {
		return "redis"
	}
	if cfg.Milvus != nil {
		return "milvus"
	}
	if cfg.Qdrant != nil {
		return "qdrant"
	}
	return "memory"
}

func resolveReplayMaxBodyBytes(maxBodyBytes int) int {
	if maxBodyBytes <= 0 {
		return routerreplay.DefaultMaxBodyBytes
	}
	return maxBodyBytes
}

func createReplayStore(
	decisionName string,
	backend string,
	pluginCfg *config.RouterReplayPluginConfig,
	globalCfg *config.RouterReplayConfig,
) (store.Storage, error) {
	switch backend {
	case "memory":
		logging.Warnf("Router replay store_backend is set to %q — all replay records "+
			"will be lost on router restart. Use \"postgres\" or \"redis\" for durable storage in production.",
			"memory")
		return createReplayMemoryStore(decisionName, pluginCfg, globalCfg), nil
	case "redis":
		return createReplayRedisStore(globalCfg)
	case "postgres":
		return createReplayPostgresStore(globalCfg)
	case "milvus":
		return createReplayMilvusStore(globalCfg)
	case "qdrant":
		return createReplayQdrantStore(globalCfg)
	default:
		return nil, fmt.Errorf(
			"unknown store_backend: %s (supported: memory, redis, postgres, milvus, qdrant)",
			backend,
		)
	}
}

func createSharedReplayStore(
	backend string,
	globalCfg *config.RouterReplayConfig,
) (store.Storage, error) {
	switch backend {
	case "redis":
		return createReplayRedisStore(globalCfg)
	case "postgres":
		return createReplayPostgresStore(globalCfg)
	case "milvus":
		return createReplayMilvusStore(globalCfg)
	case "qdrant":
		return createReplayQdrantStore(globalCfg)
	default:
		return nil, fmt.Errorf("shared replay storage not supported for backend %s", backend)
	}
}

func createReplayMemoryStore(
	decisionName string,
	pluginCfg *config.RouterReplayPluginConfig,
	globalCfg *config.RouterReplayConfig,
) store.Storage {
	maxRecords := pluginCfg.MaxRecords
	if maxRecords <= 0 {
		maxRecords = routerreplay.DefaultMaxRecords
	}
	logging.Debugf("Router replay for %s using memory backend (max_records=%d)", decisionName, maxRecords)
	return store.NewMemoryStore(maxRecords, globalCfg.TTLSeconds)
}

func createReplayRedisStore(globalCfg *config.RouterReplayConfig) (store.Storage, error) {
	if globalCfg.Redis == nil {
		return nil, fmt.Errorf("redis config required when store_backend is 'redis'")
	}

	redisConfig := buildReplayRedisConfig(globalCfg.Redis)
	storage, err := store.NewRedisStore(redisConfig, globalCfg.TTLSeconds, globalCfg.AsyncWrites)
	if err != nil {
		return nil, fmt.Errorf("failed to create redis store: %w", err)
	}
	logging.Debugf(
		"Router replay using redis backend (address=%s, key_prefix=%s, ttl=%ds, async=%v)",
		redisConfig.Address,
		redisConfig.KeyPrefix,
		globalCfg.TTLSeconds,
		globalCfg.AsyncWrites,
	)
	return storage, nil
}

func buildReplayRedisConfig(redisCfg *config.RouterReplayRedisConfig) *store.RedisConfig {
	return &store.RedisConfig{
		Address:       redisCfg.Address,
		DB:            redisCfg.DB,
		Password:      redisCfg.Password,
		UseTLS:        redisCfg.UseTLS,
		TLSSkipVerify: redisCfg.TLSSkipVerify,
		MaxRetries:    redisCfg.MaxRetries,
		PoolSize:      redisCfg.PoolSize,
		KeyPrefix:     redisCfg.KeyPrefix,
	}
}

func createReplayPostgresStore(globalCfg *config.RouterReplayConfig) (store.Storage, error) {
	if globalCfg.Postgres == nil {
		return nil, fmt.Errorf("postgres config required when store_backend is 'postgres'")
	}

	pgConfig := buildReplayPostgresConfig(globalCfg.Postgres)
	storage, err := store.NewPostgresStore(pgConfig, globalCfg.TTLSeconds, globalCfg.AsyncWrites)
	if err != nil {
		return nil, fmt.Errorf("failed to create postgres store: %w", err)
	}
	tableName := pgConfig.TableName
	if tableName == "" {
		tableName = store.DefaultPostgresTableName
	}
	logging.Debugf(
		"Router replay using postgres backend (host=%s, db=%s, table=%s, ttl=%ds, async=%v)",
		pgConfig.Host,
		pgConfig.Database,
		tableName,
		globalCfg.TTLSeconds,
		globalCfg.AsyncWrites,
	)
	return storage, nil
}

func buildReplayPostgresConfig(postgresCfg *config.RouterReplayPostgresConfig) *store.PostgresConfig {
	return &store.PostgresConfig{
		Host:            postgresCfg.Host,
		Port:            postgresCfg.Port,
		Database:        postgresCfg.Database,
		User:            postgresCfg.User,
		Password:        postgresCfg.Password,
		SSLMode:         postgresCfg.SSLMode,
		MaxOpenConns:    postgresCfg.MaxOpenConns,
		MaxIdleConns:    postgresCfg.MaxIdleConns,
		ConnMaxLifetime: postgresCfg.ConnMaxLifetime,
		TableName:       postgresCfg.TableName,
	}
}

func createReplayMilvusStore(globalCfg *config.RouterReplayConfig) (store.Storage, error) {
	if globalCfg.Milvus == nil {
		return nil, fmt.Errorf("milvus config required when store_backend is 'milvus'")
	}

	milvusConfig := buildReplayMilvusConfig(globalCfg.Milvus)
	storage, err := store.NewMilvusStore(milvusConfig, globalCfg.TTLSeconds, globalCfg.AsyncWrites)
	if err != nil {
		return nil, fmt.Errorf("failed to create milvus store: %w", err)
	}
	logging.Debugf(
		"Router replay using milvus backend (address=%s, collection=%s, ttl=%ds, async=%v)",
		milvusConfig.Address,
		milvusConfig.CollectionName,
		globalCfg.TTLSeconds,
		globalCfg.AsyncWrites,
	)
	return storage, nil
}

func buildReplayMilvusConfig(milvusCfg *config.RouterReplayMilvusConfig) *store.MilvusConfig {
	return &store.MilvusConfig{
		Address:          milvusCfg.Address,
		Username:         milvusCfg.Username,
		Password:         milvusCfg.Password,
		CollectionName:   milvusCfg.CollectionName,
		ConsistencyLevel: milvusCfg.ConsistencyLevel,
		ShardNum:         milvusCfg.ShardNum,
	}
}

func createReplayQdrantStore(globalCfg *config.RouterReplayConfig) (store.Storage, error) {
	if globalCfg.Qdrant == nil {
		return nil, fmt.Errorf("qdrant config required when store_backend is 'qdrant'")
	}

	qdrantConfig := buildReplayQdrantConfig(globalCfg.Qdrant)
	storage, err := store.NewQdrantStore(qdrantConfig, globalCfg.TTLSeconds, globalCfg.AsyncWrites)
	if err != nil {
		return nil, fmt.Errorf("failed to create qdrant store: %w", err)
	}
	logging.Debugf(
		"Router replay using qdrant backend (host=%s, port=%d, collection=%s, ttl=%ds, async=%v)",
		qdrantConfig.Host,
		qdrantConfig.Port,
		qdrantConfig.CollectionName,
		globalCfg.TTLSeconds,
		globalCfg.AsyncWrites,
	)
	return storage, nil
}

func buildReplayQdrantConfig(qdrantCfg *config.RouterReplayQdrantConfig) *store.QdrantConfig {
	return &store.QdrantConfig{
		Host:           qdrantCfg.Host,
		Port:           qdrantCfg.Port,
		APIKey:         qdrantCfg.APIKey,
		UseTLS:         qdrantCfg.UseTLS,
		CollectionName: qdrantCfg.CollectionName,
	}
}

package config

import "github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"

// RAGPluginConfig represents configuration for RAG (Retrieval-Augmented Generation) plugin
type RAGPluginConfig struct {
	// Enable RAG retrieval for this decision
	Enabled bool `json:"enabled" yaml:"enabled"`

	// Retrieval backend type: "milvus", "qdrant", "external_api", "mcp", "openai", "hybrid"
	// - "openai": Use OpenAI's file_search tool with vector stores (Responses API workflow)
	Backend string `json:"backend" yaml:"backend"`

	// Similarity threshold for retrieval (0.0-1.0)
	// Only documents with similarity >= threshold will be retrieved
	SimilarityThreshold *float32 `json:"similarity_threshold,omitempty" yaml:"similarity_threshold,omitempty"`

	// Number of top-k documents to retrieve
	TopK *int `json:"top_k,omitempty" yaml:"top_k,omitempty"`

	// Maximum context length to inject (in characters)
	// If retrieved context exceeds this, it will be truncated
	MaxContextLength *int `json:"max_context_length,omitempty" yaml:"max_context_length,omitempty"`

	// Context injection mode: "tool_role" (default) or "system_prompt"
	// - "tool_role": Inject as tool role messages (compatible with hallucination detection)
	// - "system_prompt": Prepend to system prompt
	InjectionMode string `json:"injection_mode,omitempty" yaml:"injection_mode,omitempty"`

	// Backend-specific configuration
	// Structure depends on Backend type:
	// - "milvus": MilvusRAGConfig
	// - "qdrant": QdrantRAGConfig
	// - "external_api": ExternalAPIRAGConfig
	// - "mcp": MCPRAGConfig
	// - "openai": OpenAIRAGConfig
	// - "hybrid": HybridRAGConfig
	BackendConfig *StructuredPayload `json:"backend_config,omitempty" yaml:"backend_config,omitempty"`

	// Fallback behavior when retrieval fails
	// - "skip" (default): Continue without context, log warning
	// - "block": Return error response
	// - "warn": Continue with warning header
	OnFailure string `json:"on_failure,omitempty" yaml:"on_failure,omitempty"`

	// Cache retrieved results to avoid redundant searches
	// Uses in-memory cache with TTL
	CacheResults bool `json:"cache_results,omitempty" yaml:"cache_results,omitempty"`

	// TTL for cached retrieval results (seconds)
	// Only used if CacheResults is true
	CacheTTLSeconds *int `json:"cache_ttl_seconds,omitempty" yaml:"cache_ttl_seconds,omitempty"`

	// Minimum confidence threshold for triggering retrieval
	// Only retrieve if signal confidence >= this threshold
	// If not set, retrieval is triggered regardless of confidence
	MinConfidenceThreshold *float32 `json:"min_confidence_threshold,omitempty" yaml:"min_confidence_threshold,omitempty"`
}

// GetRAGConfig returns the RAG plugin configuration for a decision
func (d *Decision) GetRAGConfig() *RAGPluginConfig {
	plugin := d.GetPlugin("rag")
	if plugin == nil || plugin.Configuration == nil {
		return nil
	}

	result := &RAGPluginConfig{}
	if err := UnmarshalPluginConfig(plugin.Configuration, result); err != nil {
		logging.Errorf("Failed to unmarshal RAG config: %v", err)
		return nil
	}
	return result
}

