18	// logRoutingDecision logs routing decision with structured logging
19	func (r *OpenAIRouter) logRoutingDecision(ctx *RequestContext, reasonCode string, originalModel string, selectedModel string, decisionName string, reasoningEnabled bool) {
20		effortForMetrics := ""
21		if reasoningEnabled && decisionName != "" {
22			effortForMetrics = r.getReasoningEffort(ctx.VSRSelectedDecision, selectedModel)
23		}
24	
25		logging.ComponentEvent("extproc", "routing_decision", map[string]interface{}{
26			"reason_code":        reasonCode,
27			"request_id":         ctx.RequestID,
28			"original_model":     originalModel,
29			"selected_model":     selectedModel,
30			"decision":           decisionName,
31			"reasoning_enabled":  reasoningEnabled,
32			"reasoning_effort":   effortForMetrics,
33			"routing_latency_ms": time.Since(ctx.ProcessingStartTime).Milliseconds(),
34		})
35		metrics.RecordRoutingReasonCode(reasonCode, selectedModel)
36	}
37	
38	// recordRoutingDecision records routing decision with tracing
39	func (r *OpenAIRouter) recordRoutingDecision(ctx *RequestContext, decisionName string, originalModel string, matchedModel string, reasoningDecision entropy.ReasoningDecision) {
40		// Start decision evaluation span
41		routingCtx, routingSpan := tracing.StartDecisionSpan(ctx.TraceContext, decisionName)
42	
43		useReasoning := reasoningDecision.UseReasoning
44		logging.ComponentDebugEvent("extproc", "reasoning_decision_applied", map[string]interface{}{
45			"request_id":        ctx.RequestID,
46			"decision":          decisionName,
47			"original_model":    originalModel,
48			"selected_model":    matchedModel,
49			"reasoning_enabled": useReasoning,
50			"confidence":        reasoningDecision.Confidence,
51			"decision_reason":   reasoningDecision.DecisionReason,
52		})
53	
54		effortForMetrics := r.getReasoningEffort(ctx.VSRSelectedDecision, matchedModel)
55		metrics.RecordReasoningDecision(requestDecisionStateKey(ctx), matchedModel, useReasoning, effortForMetrics)
56	
57		// Keep legacy attributes for backward compatibility
58		tracing.SetSpanAttributes(routingSpan,
59			attribute.String(tracing.AttrRoutingStrategy, "auto"),
60			attribute.String(tracing.AttrRoutingReason, reasoningDecision.DecisionReason),
61			attribute.String(tracing.AttrOriginalModel, originalModel),
62			attribute.String(tracing.AttrSelectedModel, matchedModel),
63			attribute.Bool(tracing.AttrReasoningEnabled, useReasoning),
64			attribute.String(tracing.AttrReasoningEffort, effortForMetrics))
65	
66		// End decision span with evaluation results
67		// matchedRules would come from signal evaluation, using empty slice for now
68		tracing.EndDecisionSpan(routingSpan, float64(reasoningDecision.Confidence), []string{}, "auto")
69		ctx.TraceContext = routingCtx
70	}
71	
72	// trackVSRDecision tracks VSR decision information in context
73	// categoryName: the category from domain classification (MMLU category)
74	// decisionName: the decision name from DecisionEngine evaluation
75	func (r *OpenAIRouter) trackVSRDecision(ctx *RequestContext, categoryName string, decisionName string, matchedModel string, useReasoning bool) {
76		ctx.VSRSelectedCategory = categoryName
77		ctx.VSRSelectedDecisionName = decisionName
78		ctx.VSRSelectedModel = matchedModel
79		if useReasoning {
80			ctx.VSRReasoningMode = "on"
81		} else {
82			ctx.VSRReasoningMode = "off"
83		}
84	}
