86	// setClearRouteCache sets the ClearRouteCache flag on the response
87	func (r *OpenAIRouter) setClearRouteCache(response *ext_proc.ProcessingResponse) {
88		if response.GetRequestBody() != nil && response.GetRequestBody().GetResponse() != nil {
89			response.GetRequestBody().GetResponse().ClearRouteCache = true
90			logging.ComponentDebugEvent("extproc", "route_cache_clear_enabled", map[string]interface{}{
91				"feature": "clear_route_cache",
92			})
93		}
94	}
95	
96	// recordRoutingLatency records the routing latency metric
97	func (r *OpenAIRouter) recordRoutingLatency(ctx *RequestContext) {
98		routingLatency := time.Since(ctx.ProcessingStartTime)
99		metrics.RecordModelRoutingLatency(routingLatency.Seconds())
100	}
101	
102	// startRouterReplay begins capturing a replay record if the router_replay plugin is enabled
103	// for the matched decision. It is safe to call multiple times; only the first call is recorded.
104	func (r *OpenAIRouter) startRouterReplay(
105		ctx *RequestContext,
106		originalModel string,
107		selectedModel string,
108		decisionName string,
109	) {
110		if !shouldStartRouterReplay(ctx) {
111			return
112		}
113	
114		populateReplaySessionIfNeeded(ctx)
115	
116		recorder := r.resolveReplayRecorder(ctx, decisionName)
117		if recorder == nil {
118			return
119		}
120	
121		configureReplayRecorder(recorder, ctx.RouterReplayPluginConfig)
122		record := buildReplayRoutingRecord(ctx, originalModel, selectedModel, decisionName)
123		if !persistReplayRecord(ctx, recorder, record) {
124			return
125		}
126	}
127	
128	func shouldStartRouterReplay(ctx *RequestContext) bool {
129		if ctx == nil || ctx.RouterReplayPluginConfig == nil || !ctx.RouterReplayPluginConfig.Enabled {
130			return false
131		}
132		return ctx.RouterReplayID == ""
133	}
134	
135	// populateReplaySessionIfNeeded fills ChatCompletionMessages and session fields
136	// when startRouterReplay runs before prepareRequestForModelRouting (e.g.
137	// fast_response, semantic-cache hit, looper-internal).
138	func populateReplaySessionIfNeeded(ctx *RequestContext) {
139		if ctx == nil {
140			return
141		}
142		if ctx.ResponseAPICtx != nil && ctx.ResponseAPICtx.IsResponseAPIRequest {
143			populateSessionTransitionFields(ctx)
144			return
145		}
146		if len(ctx.ChatCompletionMessages) > 0 {
147			populateSessionTransitionFields(ctx)
148			return
149		}
150		body := ctx.OriginalRequestBody
151		if len(body) == 0 {
152			return
153		}
154		openAIRequest, err := parseOpenAIRequest(body)
155		if err != nil {
156			return
157		}
158		ctx.ChatCompletionMessages = extractChatCompletionMessages(openAIRequest)
159		populateSessionTransitionFields(ctx)
160	}
