162	func (r *OpenAIRouter) resolveReplayRecorder(ctx *RequestContext, decisionName string) *routerreplay.Recorder {
163		recipeName := config.DefaultRecipeName
164		if ctx != nil && ctx.Routing.RecipeName() != "" {
165			recipeName = ctx.Routing.RecipeName()
166		}
167		recorder := r.ReplayRecorders[config.RoutingDecisionKey(recipeName, decisionName)]
168		if recorder != nil {
169			return recorder
170		}
171		return r.ReplayRecorder
172	}
