174	func configureReplayRecorder(
175		recorder *routerreplay.Recorder,
176		cfg *config.RouterReplayPluginConfig,
177	) {
178		recorder.SetCapturePolicy(
179			cfg.CaptureRequestBody,
180			cfg.CaptureResponseBody,
181			resolveReplayMaxBodyBytes(cfg.MaxBodyBytes),
182		)
183		recorder.SetMaxToolTraceBytes(cfg.MaxToolTraceBytes)
184		recorder.SetMaxToolTraceSteps(cfg.MaxToolTraceSteps)
185	}
