187	func buildReplayRoutingRecord(
188		ctx *RequestContext,
189		originalModel string,
190		selectedModel string,
191		decisionName string,
192	) routerreplay.RoutingRecord {
193		guardrailsEnabled, jailbreakEnabled, piiEnabled, hallucinationEnabled := replayGuardrailState(ctx)
194		decisionTier, decisionPriority := replayDecisionMetadata(ctx)
195		record := routerreplay.RoutingRecord{
196			RequestID:         ctx.RequestID,
197			SessionID:         ctx.SessionID,
198			TurnIndex:         ctx.TurnIndex,
199			Decision:          decisionName,
200			Recipe:            string(ctx.Routing.RecipeName()),
201			DecisionTier:      decisionTier,
202			DecisionPriority:  decisionPriority,
203			Category:          ctx.VSRSelectedCategory,
204			OriginalModel:     originalModel,
205			SelectedModel:     replaySelectedModel(originalModel, selectedModel),
206			ReasoningMode:     replayReasoningMode(ctx),
207			ConfidenceScore:   ctx.VSRSelectedDecisionConfidence,
208			SelectionMethod:   ctx.VSRSelectionMethod,
209			RouteDiagnostics:  buildReplayRouteDiagnostics(ctx, originalModel, selectedModel, decisionName, decisionTier, decisionPriority),
210			Learning:          buildReplayLearningDiagnostics(ctx),
211			SessionPolicy:     sessionPolicyMapForReplay(ctx),
212			Signals:           replaySignalState(ctx),
213			Projections:       replayProjectionState(ctx),
214			ProjectionScores:  cloneReplayFloat64Map(ctx.VSRProjectionScores),
215			ProjectionTrace:   cloneProjectionTraceForReplay(ctx.VSRProjectionTrace),
216			SignalConfidences: cloneReplayFloat64Map(ctx.VSRSignalConfidences),
217			SignalValues:      cloneReplayFloat64Map(ctx.VSRSignalValues),
218			ToolTrace:         buildReplayRequestToolTrace(ctx),
219			Streaming:         ctx.ExpectStreamingResponse,
220			FromCache:         ctx.VSRCacheHit,
221	
222			GuardrailsEnabled: guardrailsEnabled,
223			JailbreakEnabled:  jailbreakEnabled,
224			PIIEnabled:        piiEnabled,
225	
226			JailbreakDetected:   ctx.JailbreakDetected,
227			JailbreakType:       ctx.JailbreakType,
228			JailbreakConfidence: ctx.JailbreakConfidence,
229	
230			ResponseJailbreakDetected:   ctx.ResponseJailbreakDetected,
231			ResponseJailbreakType:       ctx.ResponseJailbreakType,
232			ResponseJailbreakConfidence: ctx.ResponseJailbreakConfidence,
233	
234			PIIDetected: ctx.PIIDetected,
235			PIIEntities: ctx.PIIEntities,
236			PIIBlocked:  ctx.PIIBlocked,
237	
238			RAGEnabled:           ctx.RAGRetrievedContext != "",
239			RAGBackend:           ctx.RAGBackend,
240			RAGContextLength:     len(ctx.RAGRetrievedContext),
241			RAGSimilarityScore:   ctx.RAGSimilarityScore,
242			CacheSimilarity:      ctx.VSRCacheSimilarity,
243			ContextTokenCount:    ctx.VSRContextTokenCount,
244			HallucinationEnabled: hallucinationEnabled,
245		}
246		if ctx.ResponseAPICtx != nil && ctx.ResponseAPICtx.IsResponseAPIRequest {
247			record.PreviousResponseID = ctx.ResponseAPICtx.PreviousResponseID
248			record.ConversationID = ctx.ResponseAPICtx.ConversationID
249		}
250		if len(ctx.OriginalRequestBody) > 0 {
251			record.RequestBody = string(ctx.OriginalRequestBody)
252		}
253	
254		// Extract structured prompt and tool-definition fields from the full
255		// request body *before* body truncation occurs in AddRecord.
256		if isResponseAPIRequest(ctx) {
257			record.Prompt, record.ToolDefinitions = extractResponseAPIPromptAndTools(ctx)
258		} else {
259			record.Prompt, record.ToolDefinitions = extractChatCompletionPromptAndTools(ctx.OriginalRequestBody)
260		}
261	
262		return record
263	}
264	
265	func replayDecisionMetadata(ctx *RequestContext) (int, int) {
266		if ctx == nil || ctx.VSRSelectedDecision == nil {
267			return 0, 0
268		}
269		return ctx.VSRSelectedDecision.Tier, ctx.VSRSelectedDecision.Priority
270	}
271	
272	func replayReasoningMode(ctx *RequestContext) string {
273		if ctx.VSRReasoningMode == "" {
274			return "off"
275		}
276		return ctx.VSRReasoningMode
277	}
278	
279	func replaySelectedModel(originalModel string, selectedModel string) string {
280		if selectedModel == "" {
281			return originalModel
282		}
283		return selectedModel
284	}
285	
286	func replaySignalState(ctx *RequestContext) routerreplay.Signal {
287		return routerreplay.Signal{
288			Keyword:      ctx.VSRMatchedKeywords,
289			Embedding:    ctx.VSRMatchedEmbeddings,
290			Domain:       ctx.VSRMatchedDomains,
291			FactCheck:    ctx.VSRMatchedFactCheck,
292			UserFeedback: ctx.VSRMatchedUserFeedback,
293			Reask:        ctx.VSRMatchedReask,
294			Preference:   ctx.VSRMatchedPreference,
295			Language:     ctx.VSRMatchedLanguage,
296			Context:      ctx.VSRMatchedContext,
297			Structure:    ctx.VSRMatchedStructure,
298			Complexity:   ctx.VSRMatchedComplexity,
299			Modality:     ctx.VSRMatchedModality,
300			Authz:        ctx.VSRMatchedAuthz,
301			Jailbreak:    ctx.VSRMatchedJailbreak,
302			PII:          ctx.VSRMatchedPII,
303			KB:           ctx.VSRMatchedKB,
304			Conversation: ctx.VSRMatchedConversation,
305			Event:        ctx.VSRMatchedEvent,
306			Metadata:     ctx.VSRMatchedMetadata,
307			Classifier:   ctx.VSRMatchedClassifier,
308		}
