310	
311	func replayProjectionState(ctx *RequestContext) []string {
312		if ctx == nil || len(ctx.VSRMatchedProjection) == 0 {
313			return nil
314		}
315		return append([]string(nil), ctx.VSRMatchedProjection...)
316	}
317	
318	func cloneReplayInterfaceMap(values map[string]interface{}) map[string]interface{} {
319		if values == nil {
320			return nil
321		}
322		b, err := json.Marshal(values)
323		if err != nil {
324			return nil
325		}
326		var cloned map[string]interface{}
327		if err := json.Unmarshal(b, &cloned); err != nil {
328			return nil
329		}
330		return cloned
331	}
332	
333	func replayGuardrailState(ctx *RequestContext) (bool, bool, bool, bool) {
334		if ctx.VSRSelectedDecision == nil {
335			return false, false, false, false
336		}
337		jailbreakEnabled := ctx.VSRSelectedDecision.HasSignalType("jailbreak")
338		piiEnabled := ctx.VSRSelectedDecision.HasSignalType("pii")
339		hallucinationEnabled := false
340		if hallucinationCfg := ctx.VSRSelectedDecision.GetHallucinationConfig(); hallucinationCfg != nil {
341			hallucinationEnabled = hallucinationCfg.Enabled
342		}
343		return jailbreakEnabled || piiEnabled, jailbreakEnabled, piiEnabled, hallucinationEnabled
344	}
345	
346	func persistReplayRecord(
347		ctx *RequestContext,
348		recorder *routerreplay.Recorder,
349		record routerreplay.RoutingRecord,
350	) bool {
351		replayID, err := recorder.AddRecord(record)
352		if err != nil {
353			logging.ComponentErrorEvent("extproc", "router_replay_persist_failed", map[string]interface{}{
354				"request_id": ctx.RequestID,
355				"decision":   record.Decision,
356				"error":      err.Error(),
357			})
358			return false
359		}
360		ctx.RouterReplayID = replayID
361		ctx.RouterReplayRecorder = recorder
362	
363		if stored, ok := recorder.GetRecord(replayID); ok {
364			logging.ComponentEvent(
365				"extproc",
366				"router_replay_start",
367				routerreplay.LogFields(stored, "router_replay_start"),
368			)
369		}
370		return true
371	}
372	
373	// updateRouterReplayStatus updates status metadata (status code, streaming/cache flags).
374	func (r *OpenAIRouter) updateRouterReplayStatus(ctx *RequestContext, status int, streaming bool) {
375		if ctx == nil || ctx.RouterReplayID == "" {
376			return
377		}
378	
379		recorder := ctx.RouterReplayRecorder
380		if recorder == nil {
381			recorder = r.ReplayRecorder
382		}
383		if recorder == nil {
384			return
385		}
386	
387		err := recorder.UpdateStatus(ctx.RouterReplayID, status, ctx.VSRCacheHit, streaming)
388		if err != nil {
389			logging.ComponentErrorEvent("extproc", "router_replay_status_update_failed", map[string]interface{}{
390				"request_id": ctx.RequestID,
391				"replay_id":  ctx.RouterReplayID,
392				"error":      err.Error(),
393			})
394		}
395	}
396	
397	// attachRouterReplayResponse stores response payload (if configured) and optionally logs completion.
398	func (r *OpenAIRouter) attachRouterReplayResponse(ctx *RequestContext, responseBody []byte, isFinal bool) {
399		if ctx == nil || ctx.RouterReplayID == "" {
400			return
401		}
402	
403		recorder := ctx.RouterReplayRecorder
404		if recorder == nil {
405			recorder = r.ReplayRecorder
406		}
407		if recorder == nil {
408			return
409		}
410	
411		if len(responseBody) > 0 {
412			_ = recorder.AttachResponse(ctx.RouterReplayID, responseBody)
413		}
414		if responseTrace := buildReplayResponseToolTrace(ctx, responseBody); responseTrace != nil {
415			if stored, ok := recorder.GetRecord(ctx.RouterReplayID); ok {
416				responseTrace = mergeReplayToolTraces(stored.ToolTrace, responseTrace)
417			}
418			if responseTrace != nil {
419				_ = recorder.UpdateToolTrace(ctx.RouterReplayID, *responseTrace)
420			}
421		}
422	
423		if isFinal {
424			if rec, ok := recorder.GetRecord(ctx.RouterReplayID); ok {
425				logging.ComponentEvent(
426					"extproc",
427					"router_replay_complete",
428					routerreplay.LogFields(rec, "router_replay_complete"),
429				)
430			}
431		}
432	}
433	
434	// hallucinationSpanDetailsForReplay converts NLI span analysis into the
435	// replay store's shape. Returns nil when NLI detection did not run for this
436	// request, so basic (non-NLI) detection continues to persist plain spans only.
437	func hallucinationSpanDetailsForReplay(info *EnhancedHallucinationInfo) []routerreplay.HallucinationSpan {
438		if info == nil {
439			return nil
440		}
441		details := make([]routerreplay.HallucinationSpan, len(info.Spans))
442		for i, span := range info.Spans {
443			details[i] = routerreplay.HallucinationSpan{
444				Text:                    span.Text,
445				Start:                   span.Start,
446				End:                     span.End,
447				HallucinationConfidence: span.HallucinationConfidence,
448				NLILabel:                span.NLILabel,
449				NLIConfidence:           span.NLIConfidence,
450				Severity:                span.Severity,
451				Explanation:             span.Explanation,
452			}
453		}
454		return details
455	}
456	
457	// updateRouterReplayHallucinationStatus updates the hallucination detection results in the replay record.
458	func (r *OpenAIRouter) updateRouterReplayHallucinationStatus(ctx *RequestContext) {
459		if ctx == nil || ctx.RouterReplayID == "" {
460			return
461		}
462	
463		// Only update if hallucination detection was enabled
464		if ctx.VSRSelectedDecision == nil {
465			return
466		}
467		hallucinationConfig := ctx.VSRSelectedDecision.GetHallucinationConfig()
468		if hallucinationConfig == nil || !hallucinationConfig.Enabled {
469			return
470		}
471	
472		recorder := ctx.RouterReplayRecorder
473		if recorder == nil {
474			recorder = r.ReplayRecorder
475		}
476		if recorder == nil {
477			return
478		}
479	
480		err := recorder.UpdateHallucinationStatus(
481			ctx.RouterReplayID,
482			ctx.HallucinationDetected,
483			ctx.HallucinationConfidence,
484			ctx.HallucinationSpans,
485			hallucinationSpanDetailsForReplay(ctx.EnhancedHallucinationInfo),
486		)
487		if err != nil {
488			logging.ComponentErrorEvent("extproc", "router_replay_hallucination_update_failed", map[string]interface{}{
489				"request_id": ctx.RequestID,
490				"replay_id":  ctx.RouterReplayID,
491				"error":      err.Error(),
492			})
493		}
494	}
495	
496	func (r *OpenAIRouter) updateRouterReplayUsageCost(ctx *RequestContext, usage routerreplay.UsageCost) {
497		if ctx == nil || ctx.RouterReplayID == "" || usage.TotalTokens == nil {
498			return
499		}
500	
501		recorder := ctx.RouterReplayRecorder
502		if recorder == nil {
503			recorder = r.ReplayRecorder
504		}
505		if recorder == nil {
506			return
507		}
508	
509		if err := recorder.UpdateUsageCost(ctx.RouterReplayID, usage); err != nil {
510			logging.ComponentErrorEvent("extproc", "router_replay_usage_update_failed", map[string]interface{}{
511				"request_id": ctx.RequestID,
512				"replay_id":  ctx.RouterReplayID,
513				"error":      err.Error(),
514			})
515		}
516	}
