1	package extproc
2	
3	import (
4		"strings"
5		"time"
6	
7		core "github.com/envoyproxy/go-control-plane/envoy/config/core/v3"
8		ext_proc "github.com/envoyproxy/go-control-plane/envoy/service/ext_proc/v3"
9	
10		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/anthropic"
11		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
12		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/headers"
13		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
14	)
15	
16	func (r *OpenAIRouter) handleNonStreamingResponseBody(
17		responseBody []byte,
18		ctx *RequestContext,
19		completionLatency time.Duration,
20		initialBodyTransformed bool,
21	) *ext_proc.ProcessingResponse {
22		usage := parseResponseUsage(responseBody, ctx.RequestModel)
23		r.reportNonStreamingUsage(ctx, completionLatency, usage)
24		r.calibrateTokenEstimator(ctx, usage.promptTokens)
25		r.updateResponseCache(ctx, responseBody)
26	
27		finalBody, clientTransformed := r.translateResponseBodyForClient(ctx, responseBody)
28		bodyMutation, headerMutation := buildInitialResponseMutations(
29			finalBody,
30			initialBodyTransformed || clientTransformed,
31		)
32	
33		if jailbreakResponse := r.performResponseJailbreakDetection(ctx, responseBody); jailbreakResponse != nil {
34			return jailbreakResponse
35		}
36		if hallucinationResponse := r.performHallucinationDetection(ctx, responseBody); hallucinationResponse != nil {
37			return hallucinationResponse
38		}
39	
40		r.scheduleResponseMemoryStore(ctx, responseBody)
41		r.markUnverifiedFactualResponse(ctx)
42	
43		response := r.applyResponseWarnings(ctx, responseBody, bodyMutation, headerMutation)
44		r.updateRouterReplayHallucinationStatus(ctx)
45		r.attachRouterReplayResponse(ctx, finalBody, true)
46		return response
47	}
48	
49	// translateResponseBodyForClient dispatches body rewriting based on the
50	// inbound client protocol. Returns the rewritten body and a flag
51	// indicating whether a rewrite happened, so callers know whether to
52	// emit a body mutation downstream.
53	//
54	// Branch order matters: ClientProtocol "anthropic" and Response API are
55	// mutually exclusive (different inbound paths — /v1/messages vs
56	// /v1/responses), but pinning the Anthropic branch first keeps the
57	// dispatcher reading top-down by likelihood.
58	func (r *OpenAIRouter) translateResponseBodyForClient(
59		ctx *RequestContext,
60		responseBody []byte,
61	) ([]byte, bool) {
62		// Defensive: a nil ctx cannot match either dispatcher branch and the
63		// downstream isResponseAPIRequest dereference would panic. Treat as
64		// plain OpenAI pass-through.
65		if ctx == nil {
66			return responseBody, false
67		}
68	
69		if ctx.ClientProtocol == config.ClientProtocolAnthropic {
70			translated, err := anthropic.EmitAnthropicResponse(responseBody, ctx.IRExtensions, ctx.RequestModel)
71			if err != nil {
72				logging.Errorf("Anthropic outbound emit failed: %v", err)
73				return anthropic.EmitAnthropicError("api_error", err.Error()), true
74			}
75			return translated, true
76		}
77	
78		if !isResponseAPIRequest(ctx) || r.ResponseAPIFilter == nil {
79			return responseBody, false
80		}
81	
82		translatedBody, err := r.ResponseAPIFilter.TranslateResponse(
83			ctx.TraceContext,
84			ctx.ResponseAPICtx,
85			responseBody,
86		)
87		if err != nil {
88			logging.Errorf("Response API translation error: %v", err)
89			return responseBody, false
90		}
91	
92		logging.Infof("Response API: Translated response to Response API format")
93		return translatedBody, true
94	}
95	
96	func buildInitialResponseMutations(
97		finalBody []byte,
98		bodyWasTransformed bool,
99	) (*ext_proc.BodyMutation, *ext_proc.HeaderMutation) {
100		if !bodyWasTransformed {
101			return nil, nil
102		}
103	
104		return &ext_proc.BodyMutation{
105				Mutation: &ext_proc.BodyMutation_Body{
106					Body: finalBody,
107				},
108			}, &ext_proc.HeaderMutation{
109				RemoveHeaders: []string{"content-length"},
110			}
111	}
112	
113	func (r *OpenAIRouter) markUnverifiedFactualResponse(ctx *RequestContext) {
114		if ctx.VSRSelectedDecision == nil {
115			return
116		}
117	
118		hallucinationConfig := ctx.VSRSelectedDecision.GetHallucinationConfig()
119		if hallucinationConfig != nil && hallucinationConfig.Enabled {
120			r.checkUnverifiedFactualResponse(ctx)
121		}
122	}
123	
124	// applyResponseWarnings consolidates the response-quality warnings into the
125	// single x-vsr-response-warnings header (#2204). Each warning either contributes
126	// its code to that header (the "header"/default action), rewrites the body with
127	// an inline warning (the "body" action), or is suppressed ("none"). Codes are
128	// collected in a fixed order so the header value is deterministic. The detail
129	// behind each warning stays in the replay record.
130	func (r *OpenAIRouter) applyResponseWarnings(
131		ctx *RequestContext,
132		responseBody []byte,
133		bodyMutation *ext_proc.BodyMutation,
134		headerMutation *ext_proc.HeaderMutation,
135	) *ext_proc.ProcessingResponse {
136		response := buildResponseBodyContinueResponse(bodyMutation, headerMutation)
137		modifiedBody := responseBody
138		var codes []string
139	
140		if ctx.HallucinationDetected {
141			var code string
142			modifiedBody, code = r.applyHallucinationWarning(ctx, modifiedBody)
143			codes = appendNonEmpty(codes, code)
144		}
145		if ctx.UnverifiedFactualResponse {
146			var code string
147			modifiedBody, code = r.applyUnverifiedFactualWarning(ctx, modifiedBody)
148			codes = appendNonEmpty(codes, code)
149		}
150		// Jailbreak never rewrites the body, so its position relative to the
151		// body-prepending warnings above is immaterial; it is appended last only to
152		// fix the code order in the header value.
153		codes = appendNonEmpty(codes, r.responseJailbreakWarningCode(ctx))
154	
155		if len(codes) > 0 {
156			setResponseWarningsHeader(response, codes)
157		}
158		if string(modifiedBody) != string(responseBody) {
159			setResponseBodyMutation(response, modifiedBody)
160		}
161		return response
162	}
163	
164	func appendNonEmpty(codes []string, code string) []string {
165		if code == "" {
166			return codes
167		}
168		return append(codes, code)
169	}
170	
171	// setResponseWarningsHeader writes the consolidated x-vsr-response-warnings header
172	// (comma-separated codes) onto the response, merging with any existing mutation.
173	func setResponseWarningsHeader(response *ext_proc.ProcessingResponse, codes []string) {
174		bodyResponse, ok := response.Response.(*ext_proc.ProcessingResponse_ResponseBody)
175		if !ok {
176			return
177		}
178		if bodyResponse.ResponseBody.Response == nil {
179			bodyResponse.ResponseBody.Response = &ext_proc.CommonResponse{}
180		}
181		opt := &core.HeaderValueOption{
182			Header: &core.HeaderValue{
183				Key:      headers.VSRResponseWarnings,
184				RawValue: []byte(strings.Join(codes, ",")),
185			},
186		}
187		if hm := bodyResponse.ResponseBody.Response.HeaderMutation; hm != nil {
188			hm.SetHeaders = append(hm.SetHeaders, opt)
189			return
190		}
191		bodyResponse.ResponseBody.Response.HeaderMutation = &ext_proc.HeaderMutation{
192			SetHeaders: []*core.HeaderValueOption{opt},
193		}
194	}
