1	package config
2	
3	import "github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
4	
5	const (
6		defaultRouterReplayMaxRecords   = 10000
7		defaultRouterReplayMaxBodyBytes = 4096
8		// defaultRouterReplayMaxToolTraceSteps caps the per-record tool-trace
9		// step count by default so an agentic session that loops forever can't
10		// drive the router to OOM (see #1835). 100 covers normal multi-tool
11		// flows without losing the user query at the head of the timeline; the
12		// truncation policy is "drop oldest" so the most recent steps stay.
13		defaultRouterReplayMaxToolTraceSteps = 100
14	)
15	
16	func DefaultRouterReplayPluginConfig() RouterReplayPluginConfig {
17		return RouterReplayPluginConfig{
18			Enabled:             true,
19			MaxRecords:          defaultRouterReplayMaxRecords,
20			CaptureRequestBody:  true,
21			CaptureResponseBody: true,
22			MaxBodyBytes:        defaultRouterReplayMaxBodyBytes,
23			MaxToolTraceSteps:   defaultRouterReplayMaxToolTraceSteps,
24		}
25	}
26	
27	// EffectiveRouterReplayConfigForDecision returns the replay configuration that
28	// should apply to a decision after layering global enablement and any
29	// per-decision router_replay plugin overrides.
30	func (c *RouterConfig) EffectiveRouterReplayConfigForDecision(decisionName string) *RouterReplayPluginConfig {
31		if c == nil {
32			base := DefaultRouterReplayPluginConfig()
33			return &base
34		}
35		return c.EffectiveRouterReplayConfig(c.GetDecisionByName(decisionName))
36	}
37	
38	// EffectiveRouterReplayConfig resolves replay policy from an already scoped
39	// decision. Request-time callers should prefer this form because decision names
40	// are recipe-local and therefore cannot identify a decision globally.
41	func (c *RouterConfig) EffectiveRouterReplayConfig(decision *Decision) *RouterReplayPluginConfig {
42		base := DefaultRouterReplayPluginConfig()
43		if c == nil {
44			return &base
45		}
46		base.Enabled = c.RouterReplay.Enabled
47	
48		if decision == nil {
49			if base.Enabled {
50				return &base
51			}
52			return nil
53		}
54	
55		plugin := decision.GetPlugin(DecisionPluginRouterReplay)
56		if plugin == nil {
57			if base.Enabled {
58				return &base
59			}
60			return nil
61		}
62		if plugin.Configuration == nil {
63			if base.Enabled {
64				return &base
65			}
66			return nil
67		}
68	
69		if err := UnmarshalPluginConfig(plugin.Configuration, &base); err != nil {
70			logging.Errorf("Failed to unmarshal %s config: %v", DecisionPluginRouterReplay, err)
71			return nil
